-- Development / test fixture. Small, but deliberately covers the awkward cases:
-- multi-form species, a form that cannot be deposited into HOME, names that differ
-- across languages, two-character CJK names that fall below the FTS5 trigram floor,
-- and languages that are missing. Identifiers follow PokéAPI's; HOME games are
-- illustrative, not real. The real dataset is generated by `bun run data:build`.

DELETE FROM evolution;
DELETE FROM encounter;
DELETE FROM form_home_game;
DELETE FROM form_ability;
DELETE FROM form_type;
DELETE FROM form;
DELETE FROM pokemon_dex_number;
DELETE FROM pokemon_origin;
DELETE FROM pokemon_egg_group;
DELETE FROM pokemon;
DELETE FROM generation;
DELETE FROM type;
DELETE FROM ability;
DELETE FROM move;
DELETE FROM meta;


